#include "combined.hpp"
#include <array>
#include <chrono>
#include <cstdint>
#include <ctime>
#include <iostream>
#include <random>
#include <string>
using Matrix = std::vector<std::vector<std::uint32_t>>;
using Function = Matrix(*)(const Matrix&);
std::uint64_t run(Function function, const Matrix& input, int loops) {
    std::uint64_t sum = 0;
    for (int i = 0; i < loops; ++i) {
        const auto out = function(input);
        sum += out[(std::size_t(i) * 17) % out.size()][(std::size_t(i) * 31) % out.front().size()];
    }
    return sum;
}
int main(int argc, char** argv) {
    if (argc != 5) return 1;
    const auto h = std::stoull(argv[1]), w = std::stoull(argv[2]);
    const int mode = std::stoi(argv[3]), repetitions = std::stoi(argv[4]);
    Matrix input(h, std::vector<std::uint32_t>(w));
    std::mt19937 random(261022);
    for (auto& row : input) for (auto& value : row) value = random();
    const std::array<Function,3> functions = mode == 0 ? std::array<Function,3>{baseline::transpose<std::uint32_t>, control::transpose<std::uint32_t>, avx2::transpose<std::uint32_t>} : mode == 1 ? std::array<Function,3>{baseline::rotate_90r<std::uint32_t>, control::rotate_90r<std::uint32_t>, avx2::rotate_90r<std::uint32_t>} : std::array<Function,3>{baseline::rotate_90l<std::uint32_t>, control::rotate_90l<std::uint32_t>, avx2::rotate_90l<std::uint32_t>};
    const auto reference = functions[0](input);
    for (auto f : functions) if (f(input) != reference) return 2;
    auto start = std::chrono::steady_clock::now();
    const auto pilot = run(functions[0],input,1);
    const double pilot_ms = std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();
    const int loops = std::max(1,std::min(5000,int(0.7/std::max(pilot_ms,0.0001))));
    std::uint64_t checksum = pilot;
    for (int rep = 0; rep < repetitions; ++rep) {
        std::array<std::uint64_t,3> sums{};
        for (int k = 0; k < 3; ++k) {
            const int v = (k + rep) % 3;
            const auto cpu_start = std::clock(); start = std::chrono::steady_clock::now();
            sums[v] = run(functions[v],input,loops);
            const double wall_ns = std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-start).count()/loops;
            const double cpu_ns = double(std::clock()-cpu_start)/CLOCKS_PER_SEC*1e9/loops;
            std::cout << rep << ' ' << v << ' ' << loops << ' ' << wall_ns << ' ' << cpu_ns << ' ' << sums[v] << '\n';
            checksum += sums[v];
        }
        if (sums[0]!=sums[1] || sums[0]!=sums[2]) return 3;
    }
    std::cerr << checksum << '\n';
}

